ALTER TABLE "leave_requests" DROP CONSTRAINT "leave_requests_status";--> statement-breakpoint
ALTER TABLE "leave_requests" ADD COLUMN "decision_reason" text;--> statement-breakpoint
ALTER TABLE "leave_requests" ADD COLUMN "revoked_by" uuid;--> statement-breakpoint
ALTER TABLE "leave_requests" ADD COLUMN "revoked_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "leave_requests" ADD COLUMN "revocation_reason" text;--> statement-breakpoint
ALTER TABLE "leave_requests" ADD CONSTRAINT "leave_requests_revoked_by_user_id_fk" FOREIGN KEY ("revoked_by") REFERENCES "public"."user"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "leave_requests" ADD CONSTRAINT "leave_requests_decision_reason" CHECK ("leave_requests"."decision_reason" IS NULL OR (char_length("leave_requests"."decision_reason") BETWEEN 1 AND 500 AND "leave_requests"."decision_reason"=btrim("leave_requests"."decision_reason")));--> statement-breakpoint
ALTER TABLE "leave_requests" ADD CONSTRAINT "leave_requests_revocation" CHECK (("leave_requests"."revoked_by" IS NULL AND "leave_requests"."revoked_at" IS NULL AND "leave_requests"."revocation_reason" IS NULL) OR ("leave_requests"."status"='CANCELLED' AND "leave_requests"."revoked_by" IS NOT NULL AND "leave_requests"."revoked_at" IS NOT NULL AND "leave_requests"."revoked_at"<"leave_requests"."starts_at" AND "leave_requests"."revocation_reason" IS NOT NULL AND char_length("leave_requests"."revocation_reason") BETWEEN 1 AND 500 AND "leave_requests"."revocation_reason"=btrim("leave_requests"."revocation_reason") AND "leave_requests"."decided_by" IS NOT NULL AND "leave_requests"."decided_at" IS NOT NULL AND "leave_requests"."cancelled_by" IS NULL AND "leave_requests"."cancelled_at" IS NULL AND "leave_requests"."rejection_reason" IS NULL));--> statement-breakpoint
ALTER TABLE "leave_requests" ADD CONSTRAINT "leave_requests_status" CHECK (("leave_requests"."status"='PENDING' AND "leave_requests"."cancelled_by" IS NULL AND "leave_requests"."cancelled_at" IS NULL AND "leave_requests"."decided_by" IS NULL AND "leave_requests"."decided_at" IS NULL AND "leave_requests"."rejection_reason" IS NULL AND "leave_requests"."decision_reason" IS NULL AND "leave_requests"."revoked_by" IS NULL) OR ("leave_requests"."status"='CANCELLED' AND "leave_requests"."rejection_reason" IS NULL AND (("leave_requests"."cancelled_by" IS NOT NULL AND "leave_requests"."cancelled_at" IS NOT NULL AND "leave_requests"."decided_by" IS NULL AND "leave_requests"."decided_at" IS NULL AND "leave_requests"."decision_reason" IS NULL AND "leave_requests"."revoked_by" IS NULL) OR ("leave_requests"."cancelled_by" IS NULL AND "leave_requests"."cancelled_at" IS NULL AND "leave_requests"."decided_by" IS NOT NULL AND "leave_requests"."decided_at" IS NOT NULL AND "leave_requests"."revoked_by" IS NOT NULL))) OR ("leave_requests"."status" IN ('APPROVED','REJECTED') AND "leave_requests"."decided_by" IS NOT NULL AND "leave_requests"."decided_at" IS NOT NULL AND "leave_requests"."cancelled_by" IS NULL AND "leave_requests"."cancelled_at" IS NULL AND "leave_requests"."revoked_by" IS NULL AND (("leave_requests"."status"='APPROVED' AND "leave_requests"."rejection_reason" IS NULL) OR ("leave_requests"."status"='REJECTED' AND "leave_requests"."rejection_reason" IS NOT NULL AND char_length(btrim("leave_requests"."rejection_reason")) BETWEEN 1 AND 500 AND ("leave_requests"."decision_reason" IS NULL OR "leave_requests"."decision_reason"="leave_requests"."rejection_reason")))));